-- Hyprland config (Lua). Migrated from hyprland.conf (hyprlang) for Hyprland >= 0.55.
-- hyprlang is deprecated since 0.55 and will be dropped; see https://hypr.land/news/26_lua/
-- Docs: https://wiki.hypr.land/Configuring/
--
-- NOTE: hyprland.conf is kept next to this file purely as a rollback. Hyprland only
-- looks for hyprland.lua at STARTUP -- if it exists it wins and the .conf is ignored.
-- To roll back: mv hyprland.lua hyprland.lua.off  (then restart the session).

-- Theme colors, generated by the gtheme `hyprland-colors` pattern (post-script derives
-- colors/colors.lua from colors/colors.conf, which hyprlock still reads as hyprlang).
local colors = require("colors.colors")


------------------
---- MONITORS ----
------------------

-- Generated by the gtheme `hyprland-monitor` pattern.
require("monitors")


---------------------
---- MY PROGRAMS ----
---------------------

local terminal    = "kitty"
local fileManager = "thunar"
local menu        = "rofi -show drun"


-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
    -- Activa la sesión gráfica de systemd (necesario para xdg-desktop-portal / screen share)
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP HYPRLAND_INSTANCE_SIGNATURE XDG_SESSION_TYPE && systemctl --user start hyprland-session.target")

    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("waybar")
    hl.exec_cmd("swaync")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("qs --path ~/.config/quickshell/hypr-overview")
    hl.exec_cmd("qs --path ~/.config/quickshell/hypr-lens")
    hl.exec_cmd("playerctld")
    hl.exec_cmd("swayosd-server")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("udiskie")
    hl.exec_cmd("qs --path ~/.config/quickshell/music")
    hl.exec_cmd("sattyd --daemon --copy-command wl-copy --early-exit --output-filename $HOME/pictures/screenshots/satty-%Y%m%d-%H%M%S.png")
end)


