-- Ignore maximize requests from apps
hl.window_rule({
    name  = "windowrule-1",
    match = { class = ".*" },
    suppress_event = "maximize",
})

-- Fix some dragging issues with XWayland
hl.window_rule({
    name  = "windowrule-2",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },
    no_focus = true,
})

hl.window_rule({ name = "windowrule-3", match = { class = "^([Mm]pv|vlc)$" },                                                  tag = "+multimedia_video" })
hl.window_rule({ name = "windowrule-4", match = { class = "^(nm-applet|nm-connection-editor|blueman-manager|org.gnome.FileRoller)$" }, tag = "+settings" })
hl.window_rule({ name = "windowrule-5", match = { class = "^(org.gnome.DiskUtility|wihotspot(-gui)?)$" },                      tag = "+settings" })
hl.window_rule({ name = "windowrule-6", match = { class = "^(org.gnome.SystemMonitor)$" },                                     tag = "+viewer" })
hl.window_rule({ name = "windowrule-7", match = { class = "^(org.gnome.Evince)$" },                                            tag = "+viewer" })
hl.window_rule({ name = "windowrule-8", match = { class = "^(eog|org.gnome.Loupe)$" },                                         tag = "+viewer" })

hl.window_rule({
    name    = "windowrule-9",
    match   = { tag = "multimedia_video*" },
    no_blur = true,
    opacity = "1.0",
    float   = true,
    size    = {900, 506},
})

hl.window_rule({ name = "windowrule-10", match = { tag = "settings*" },                                          opacity = "0.8", float = true })
