    name         = "layerrule-6",
    match        = { namespace = "swaync-control-center" },
    blur         = true,
    ignore_alpha = 0.5,
    xray         = false,
    animation    = "slide right 60%",
})

hl.layer_rule({
    name         = "layerrule-7",
    match        = { namespace = "swaync-notification-window" },
    blur         = true,
    ignore_alpha = 0.5,
    xray         = false,
    animation    = "slide 60%",
})
